# Definition of predefined shapes as a list of dictionaries in which each dict
# has "type": a str, "points": a list of tuple[float, float] → 2D coordinates.
# the list can be generated by functions

import numpy as np

def regular_polygon(n_sides: int) -> list:
    """
    Generates a closed regular polygon with n_sides sides.
    Coordinates are normalised to [-1, 1] and centred at (0, 0).
    Output: list of sections of the form {'type': 'line', 'points': [p1, p2]}
    """
    if n_sides < 3:
        raise ValueError("The number of sides must be at least 3")

    # Equally spaced angles
    angles = np.linspace(0, 2 * np.pi, n_sides, endpoint=False)
    points = [(np.cos(a), np.sin(a)) for a in angles]

    # Normalise to range [-1, 1] (if not already)
    max_abs = max(max(abs(x), abs(y)) for x, y in points)
    points = [(x / max_abs, y / max_abs) for x, y in points]

    # Create the sections (closing the polygon)
    sections = []
    for i in range(n_sides):
        p1 = points[i]
        p2 = points[(i + 1) % n_sides]  # next (wrapping around)
        sections.append({"type": "line", "points": [p1, p2]})

    return sections

def ellipse_spline(n_points: int = 8) -> list:
    """
    Generates a closed ellipse using n_points control points.
    The ellipse is centred at (0, 0) and within the range [-1, 1] in x and y.
    Returns a single section of type 'spline'.
    """
    if n_points < 3:
        raise ValueError("The ellipse must have at least 3 control points")

    # Generate points on the ellipse (deformed circle)
    angles = np.linspace(0, 2 * np.pi, n_points+1, endpoint=True)
    a, b = 1.0, 1.0  # Semi-axes (change to other values for a non-circular ellipse)
    points = [(a * np.cos(t), b * np.sin(t)) for t in angles]

    # Return as a closed spline
    return [{"type": "spline", "points": points}]

SHAPES = {
    "triangle":  [regular_polygon(3)],
    "square":  [regular_polygon(4)],
    "pentagon": [regular_polygon(5)],
    "hexagon": [regular_polygon(6)],
    "ellipse":  [ellipse_spline(12)],
    "oval": [[
        {"type": "line", "points": [(0.5, 0.5), (-0.5, 0.5)]},
        {"type": "spline", "points": [(-0.5, 0.5), (-1, 0), (-0.5, -0.5)]},
        {"type": "line", "points": [(-0.5,-0.5), (0.5, -0.5)]},
        {"type": "spline", "points": [(0.5, -0.5), (1, 0), (0.5, 0.5)]},
    ]],
    "line": [[
        {"type": "line", "points": [(-1.0, 0.0), (0.0, 0.0)]},
        {"type": "line", "points": [(0.0, 0.0), (1.0, 0.0)]},
    ]],
    "bacillus": [[
        {"type": "line", "points": [(0.5, 1.0), (-0.5, 1.0)]},
        {"type": "spline", "points": [(-0.5, 1.0), (-1, 0), (-0.5, -1.0)]},
        {"type": "line", "points": [(-0.5,-1.0), (0.5, -1.0)]},
        {"type": "spline", "points": [(0.5, -1.0), (1, 0), (0.5, 1.0)]},
    ], ellipse_spline(12)],
    "cocos": [ellipse_spline(12)],
}